 function saveCommand(type,args=[],refresh=true){const result=window.QiheSaves.command(type,...args);if(result.ok&&!result.navigating&&refresh)saveManager(type==='create'?'active':s.saveView);if(!result.ok){if(s.detail&&!['新建存档','重命名存档'].includes(s.detail.title))renderDetail();else if(!s.detail)panel.querySelector('.qj-overlay').hidden=true}notify(result.message||result.reason);return result}
